on conflict (term_type, term_key) do update
set label_ko = excluded.label_ko,
    label_en = excluded.label_en,
    synonyms = excluded.synonyms,
    parent_term_key = excluded.parent_term_key,
    applicable_sections = excluded.applicable_sections,
    metadata = excluded.metadata,
    taxonomy_version = excluded.taxonomy_version,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active,
    updated_at = now();

with folded(term_key, target) as (
  values
    ('hop', 'herbal'),
    ('matcha', 'green_tea'),
    ('red_cherry', 'cherry')
)
update public.alcohol_tasting_profiles as profile
set aroma_tags = coalesce((
        select array_agg(s.tag order by s.first)
        from (
          select coalesce(folded.target, x.tag) as tag, min(x.ord) as first
          from unnest(profile.aroma_tags) with ordinality as x(tag, ord)
          left join folded on folded.term_key = x.tag
          group by 1
        ) s), array[]::text[]),
    palate_tags = coalesce((
        select array_agg(s.tag order by s.first)
        from (
          select coalesce(folded.target, x.tag) as tag, min(x.ord) as first
          from unnest(profile.palate_tags) with ordinality as x(tag, ord)
          left join folded on folded.term_key = x.tag
          group by 1
        ) s), array[]::text[]),
    finish_tags = coalesce((
        select array_agg(s.tag order by s.first)
        from (
          select coalesce(folded.target, x.tag) as tag, min(x.ord) as first
          from unnest(profile.finish_tags) with ordinality as x(tag, ord)
          left join folded on folded.term_key = x.tag
          group by 1
        ) s), array[]::text[])
where (profile.aroma_tags || profile.palate_tags || profile.finish_tags)
  && array(select term_key from folded);

-- Every descriptor row written above carries this transaction's now(); what
-- is left is no longer in the dictionary's projection.
delete from public.catalog_taxonomy
where term_type = 'sensory_descriptor'
  and updated_at < now();

commit;
